#include <iostream>
#include <unordered_set>
#include <vector>

int countUnique(const std::vector<int>& nums) {
    std::unordered_set<int> distinct(nums.begin(), nums.end());
    return static_cast<int>(distinct.size());
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::cout << countUnique(nums) << "\n";
    return 0;
}

