package main

import "fmt"

func countUnique(nums []int) int {
	seen := make(map[int]bool)
	for _, x := range nums {
		seen[x] = true
	}
	return len(seen)
}

func main() {
	var n int
	fmt.Scan(&n)
	nums := make([]int, n)
	for i := range nums {
		fmt.Scan(&nums[i])
	}
	fmt.Println(countUnique(nums))
}
